fn voyage_key_from_file() -> Option<String> {
    let path = std::env::var("COGNITIVE_MCP_VOYAGE_KEY_FILE")
        .ok()
        .map(PathBuf::from)
        .or_else(|| {
            std::env::var_os("HOME").map(|home| Path::new(&home).join(".ssh/mongo-voyage"))
        })?;

    let contents = std::fs::read_to_string(&path).ok()?;
    let key = contents
        .lines()
        .map(str::trim)
        .find(|line| {
            !line.is_empty()
                && !line.starts_with('#')
                && !line.starts_with("mdb_sa_id_")
                && !line.starts_with("mdb_sa_sk_")
                && (line.starts_with("al-") || line.starts_with("pa-"))
        })?
        .to_string();

    tracing::info!(path = %path.display(), "Loaded Voyage API key from file");
    Some(key)
}

fn voyage_url_for_key(key: &str) -> &'static str {
    if key.trim().starts_with("al-") {
        DEFAULT_VOYAGE_MONGODB_API_URL
    } else {
        DEFAULT_VOYAGE_API_URL
    }
}

#[derive(Serialize)]
struct VoyageEmbeddingRequest<'a> {
    input: &'a str,
    model: &'a str,
    input_type: &'a str,
    truncation: bool,
    output_dimension: u32,
    output_dtype: &'a str,
}

fn read_identity_sled(path: &Path) -> Result<IdentitySled> {
    let file = File::open(path)
        .with_context(|| format!("failed to open SchemaEngine sled at {}", path.display()))?;
    // SAFETY: The file is opened read-only and we only read a validated-length region.
    // The mmap is dropped before this function returns, so no dangling pointers escape.
    let mmap = unsafe { MmapOptions::new().map(&file) }
        .with_context(|| format!("failed to mmap SchemaEngine sled at {}", path.display()))?;

    ensure!(
        mmap.len() >= size_of::<IdentitySled>(),
        "SchemaEngine sled at {} is smaller than IdentitySled ABI ({})",
        path.display(),
        size_of::<IdentitySled>()
    );

    let sled_ptr = mmap.as_ptr().cast::<IdentitySled>();
    // SAFETY: We validated mmap.len() >= size_of::<IdentitySled>() above, so the pointer is
    // within the mapped region. read_unaligned is safe because we only copy the value out.
    let sled = unsafe { std::ptr::read_unaligned(sled_ptr) };

    Ok(sled)
}

fn read_plugin_schema(_path: &Path) -> Result<PluginSchema> {
    // The sealed blob IS the plugin: the active session schema is read from
    // the plugin's own blob in the SHM catalog. `OP_ACTIVE_SCHEMA_PLUGIN`
    // selects which plugin anchors the session's retrieval text.
    let plugin_id = std::env::var("OP_ACTIVE_SCHEMA_PLUGIN")
        .unwrap_or_else(|_| "ctl_plane_chatbot".to_string());
    if let Some(schema) = op_blob::catalog::read_plugin_schema_shm(&plugin_id) {
        return Ok(schema);
    }
    // Transitional fallback: a sled-embedded single schema from hosts not yet
    // re-sealed with a blob catalog.
    let schema_bytes = op_identity::read_schema_blob().with_context(|| {
        format!("no sealed blob for '{plugin_id}' and no sled-embedded schema available")
    })?;
    parse_plugin_schema(schema_bytes, Path::new("(sled-embedded schema blob)"))
}

fn read_identity_sled_and_schema(path: &Path) -> Result<(IdentitySled, PluginSchema)> {
    let sled = read_identity_sled(path)?;
    let schema = read_plugin_schema(path)?;
    Ok((sled, schema))
}

fn parse_plugin_schema(schema_bytes: Vec<u8>, path: &Path) -> Result<PluginSchema> {
    ensure!(
        !schema_bytes.is_empty(),
        "Schema file at {} is empty",
        path.display()
    );

    serde_json::from_slice(&schema_bytes)
        .with_context(|| format!("failed to parse PluginSchema from {}", path.display()))
}

fn format_trace_id(hashed_footprint: [u8; 32]) -> String {
    format!("trace-{}", hex::encode(hashed_footprint))
}

/// Returns (plugin_id, embedding_text) for every active plugin in the SHM
/// blob catalog. The multi-plugin counterpart to `current_schema_embedding_text`,
/// which only ever covers the single sled-resident schema.
fn all_blob_embedding_texts() -> Result<Vec<(String, String)>> {
    let ids = op_blob::catalog::read_manifest_plugin_ids_shm()
        .context("SHM blob manifest is unavailable")?;
    Ok(ids
        .into_iter()
        .filter_map(|id| {
            op_blob::catalog::read_plugin_schema_shm(&id)
                .map(|schema| (id, render_schema_embedding_text(&schema)))
        })
        .collect())
}

/// Deterministic UUID v5 from a plugin id, so `refresh_blob_vectors` upserts
/// idempotently in place instead of accumulating duplicate points.
fn plugin_id_to_uuid(plugin_id: &str) -> uuid::Uuid {
    // Project-local namespace for blob_vectors point ids. Fixed and arbitrary
    // (generated once) — must never change, or a refresh would orphan every
    // existing point instead of overwriting it.
    const BLOB_VECTORS_NAMESPACE: uuid::Uuid =
        uuid::Uuid::from_u128(0x8f2b_6c4a_0d1e_4a3f_9b7c_2e5d1a6f8c3b);
    uuid::Uuid::new_v5(&BLOB_VECTORS_NAMESPACE, plugin_id.as_bytes())
}

#[derive(Debug, Serialize)]
pub struct RefreshBlobVectorsSummary {
    pub embedded: usize,
    pub collection: String,
}

fn render_schema_embedding_text(schema: &PluginSchema) -> String {
    let mut lines = vec![
        format!("schema_name: {}", schema.name),
        format!("schema_category: {}", schema.category),
        format!("schema_version: {}", schema.version),
        format!("schema_description: {}", schema.description.trim()),
    ];

    let mut tags = schema.tags.clone();
    tags.sort();
    if !tags.is_empty() {
        lines.push(format!("schema_tags: {}", tags.join(", ")));
    }

    let mut immutable_paths = schema.immutable_paths.clone();
    immutable_paths.sort();
    if !immutable_paths.is_empty() {
        lines.push(format!("immutable_paths: {}", immutable_paths.join(", ")));
    }

    let mut dependencies = schema.dependencies.clone();"}

{"content":"//! Snowball vector projection: chain block -> Voyage embedding -> chain
//! vector subvolume, with Qdrant filled on the replica after `btrfs receive`.
//!
//! **Strict automatic invariant:** the streaming / default `project` path must
//! **not** upsert Qdrant on the origin. Vectors land in the chain first
//! ([`StreamingSnowball::attach_vector`] / `vectors/vec-*.bin`); the automatic
//! pipeline fills `snowball_footprints` only via **`btrfs receive` →
//! [`ChainVectorIndex::ingest_received`]** (replica hook). Orthogonal paths
//! (`blob_vectors`, user_memory, RAG shuttle) are unrelated and untouched.
//!
//! Split by role:
//!
//! - **Origin, automatic** ([`ChainVectorIndex::project_pending`] with
//!   `upsert_qdrant = false`): embed pending blocks with Voyage, write raw LE
//!   f32 into the `vectors` subvolume, stop. No Qdrant write, no index
//!   watermark bump. Snapshots carry the vectors to the replica.
//!
//! - **Replica, automatic** ([`ChainVectorIndex::ingest_received`]): after
//!   incremental `btrfs receive`, upsert only vectors that arrived (watermark +
//!   gap check). No Voyage key, no re-embedding.
//!
//! - **Manual exception** (`project_pending(..., upsert_qdrant = true)` /
//!   CLI `--upsert-qdrant`, or [`ChainVectorIndex::reindex_from_chain`]):
//!   explicit direct Qdrant write that **bypasses send/receive**. Not the
//!   default streaming path.
//!
//! Qdrant remains a disposable index: rebuild from any chain (or received
//! snapshot) that already holds the vectors.

use anyhow::{Context, Result};
use op_snowball::btrfs_delta;
use op_snowball::{ChainBlockRef, StreamingSnowball};
use qdrant_client::qdrant::{
    CreateCollectionBuilder, Distance, GetPointsBuilder, PointId, PointStruct, QueryPointsBuilder,
    ScoredPoint, UpsertPointsBuilder, VectorParamsBuilder,
};
use qdrant_client::{Payload, Qdrant, QdrantError};
use serde::Serialize;
use std::collections::HashSet;
use std::path::{Path, PathBuf};

use crate::voyage::VoyageClient;

const DEFAULT_CHAIN_PATH: &str = "/var/lib/opdbus/snowball";
const DEFAULT_COLLECTION: &str = "snowball_footprints";
const DEFAULT_DIMS: u64 = 1024;

/// Namespace for deriving deterministic Qdrant point ids from block hashes.
/// Fixed forever: changing it orphans every previously indexed point instead of
/// overwriting it.
const BLOCK_POINT_NAMESPACE: uuid::Uuid =
    uuid::Uuid::from_u128(0x6d1f_28c7_4b93_4f0a_9e57_31c8_ab4d_7e62);

/// File holding the highest block number whose vector has been indexed.
const INDEXED_BLOCK_FILE: &str = ".vector-index-block";

pub struct ChainVectorIndex {
    chain: StreamingSnowball,
    chain_path: PathBuf,
    qdrant: Qdrant,
    collection: String,
    dims: u64,
    /// `None` on a replica: ingesting received vectors needs no embedder.
    voyage: Option<VoyageClient>,
}

#[derive(Debug, Serialize, PartialEq, Eq)]
pub struct ProjectionSummary {
    pub embedded: usize,
    pub already_present: usize,
    /// Points written directly to Qdrant on this pass.
    ///
    /// Always `0` for the automatic project path. Non-zero only when the
    /// explicit manual `--upsert-qdrant` / `upsert_qdrant: true` exception is set
    /// (bypasses send/receive).
    pub upserted_to_qdrant: usize,
    pub collection: String,
}

/// Whether an origin `project` call may write Qdrant directly.
///
/// Automatic pipeline always returns `false`. Only the explicit manual
/// exception (`--upsert-qdrant`) returns `true`.
pub fn project_writes_qdrant(upsert_qdrant: bool) -> bool {
    upsert_qdrant
}

#[derive(Debug, Serialize, PartialEq, Eq)]
pub struct IngestSummary {
    pub upserted: usize,
    pub skipped: usize,
    /// Highest block number already indexed before this pass.
    pub from_block: u64,
    /// Highest block number indexed after it — the persisted watermark.
    pub to_block: u64,
    /// btrfs generation of the vector subvolume, for observability only.
    pub generation: u64,
    pub collection: String,
}

impl ChainVectorIndex {
    /// Origin side: embeds into the chain (and optionally Qdrant when the
    /// caller passes the manual upsert flag). Requires a Voyage key.
    pub async fn open() -> Result<Self> {
        let voyage = VoyageClient::new().context(
            "snowball vector projection needs a Voyage key (see embedding_model plugin)",
        )?;
        Self::build(Some(voyage)).await
    }

    /// Replica / automatic index path: indexes vectors that arrived in a btrfs
    /// stream. No embedder, so it works on a host that has no Voyage credentials
    /// at all.
    pub async fn open_replica() -> Result<Self> {
        Self::build(None).await
    }

    async fn build(voyage: Option<VoyageClient>) -> Result<Self> {
        let chain_path = PathBuf::from(
            std::env::var("OPDBUS_SNOWBALL_PATH")
                .unwrap_or_else(|_| DEFAULT_CHAIN_PATH.to_string()),
        );
        let url = qdrant_url();
        let collection = std::env::var("OPDBUS_QDRANT_SNOWBALL_COLLECTION")
            .unwrap_or_else(|_| DEFAULT_COLLECTION.to_string());
        let dims = std::env::var("OPDBUS_QDRANT_SNOWBALL_DIM")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(DEFAULT_DIMS);

        let chain = StreamingSnowball::new(&chain_path)
            .await
            .with_context(|| format!("failed to open chain at {}", chain_path.display()))?;

        let qdrant = Qdrant::from_url(&url)
            .build()
            .with_context(|| format!("failed to build Qdrant client for {url}"))?;
        qdrant
            .health_check()
            .await
            .with_context(|| format!("Qdrant unreachable at {url}"))?;

        let index = Self {
            chain,
            chain_path,
            qdrant,
            collection,
            dims,
            voyage,
        };
        index.ensure_collection().await?;
        Ok(index)
    }

    /// Create the collection on first use. Idempotent, and tolerant of a
    /// concurrent creator.
    async fn ensure_collection(&self) -> Result<()> {
        if self
            .qdrant
            .collection_exists(&self.collection)
            .await
            .with_context(|| format!("failed to probe collection '{}'", self.collection))?
        {
            return Ok(());
        }

        match self
            .qdrant
            .create_collection(
                CreateCollectionBuilder::new(&self.collection)
                    .vectors_config(VectorParamsBuilder::new(self.dims, Distance::Cosine)),
            )
            .await
        {
            Ok(_) => {
                tracing::info!(
                    collection = %self.collection,
                    dims = self.dims,
                    "created Qdrant collection for snowball vectors"
                );
                Ok(())
            }
            Err(err) if is_already_exists(&err) => Ok(()),
            Err(err) => Err(anyhow::Error::from(err)
                .context(format!("failed to create collection '{}'", self.collection))),
        }
    }

    /// Embed every block that has no vector yet and write it into the chain.
    ///
    /// **Automatic default** (`upsert_qdrant = false`): Voyage + `attach_vector`
    /// only. Does **not** upsert Qdrant and does **not** advance the Qdrant
    /// watermark — the replica's `ingest_received` owns that after `btrfs
    /// receive`.
    ///
    /// **Manual exception** (`upsert_qdrant = true`): also upserts Qdrant on
    /// this host and advances the watermark. That bypasses send/receive; use
    /// only via an explicit CLI flag / CallMethod, never as the streaming
    /// default.
    ///
    /// `limit` caps one pass so a large backlog can be worked through in
    /// bounded chunks.
    pub async fn project_pending(
        &self,
        limit: Option<usize>,
        upsert_qdrant: bool,
    ) -> Result<ProjectionSummary> {
        let voyage = self
            .voyage
            .as_ref()
            .context("project_pending requires an embedder; this index was opened as a replica")?;
        let write_qdrant = project_writes_qdrant(upsert_qdrant);

        let all = self.chain.blocks().await?;
        let already_present = all.iter().filter(|block| block.has_vector).count();
        let pending: Vec<ChainBlockRef> = all
            .into_iter()
            .filter(|block| !block.has_vector)
            .take(limit.unwrap_or(usize::MAX))
            .collect();

        let mut embedded = 0usize;
        let mut upserted_to_qdrant = 0usize;
        for block in &pending {
            let vector = voyage
                .embed(&block.embedding_text(), Some("document"))
                .await
                .with_context(|| format!("failed to embed block {}", block.block_num))?;
            let vector = self.fit_dims(vector, block.block_num)?;

            // Chain first: the vector is durable state; automatic Qdrant is
            // derived only after receive → ingest on the replica.
            self.chain.attach_vector(block.block_num, &vector).await?;
            if write_qdrant {
                self.upsert_block(block, vector).await?;
                upserted_to_qdrant += 1;
            }
            embedded += 1;
        }

        // Watermark tracks Qdrant coverage, not chain vector coverage. Bump it
        // only when this pass actually wrote the index (manual exception).
        if write_qdrant {
            if let Some(highest) = pending.iter().map(|block| block.block_num).max() {
                let watermark = self.read_indexed_block().await?.max(highest);
                self.write_indexed_block(watermark).await?;
            }
        }

        tracing::info!(
            collection = %self.collection,
            embedded,
            already_present,
            upserted_to_qdrant,
            write_qdrant,
            "snowball vector projection pass complete"
        );

        Ok(ProjectionSummary {
            embedded,
            already_present,
            upserted_to_qdrant,
            collection: self.collection.clone(),
        })
    }

    /// Manual: rebuild the index from vectors already in the chain, without
    /// embedding and **without** waiting for `btrfs receive`.
    ///
    /// Disaster-recovery / operator catch-up on a host that already has chain
    /// vectors on disk. This is **not** the automatic replication path —
    /// prefer `ingest_received` after receive when filling the replica index.
    /// No Voyage key and no re-embedding spend.
    pub async fn reindex_from_chain(&self) -> Result<IngestSummary> {
        let blocks = self.chain.blocks().await?;
        let mut upserted = 0usize;
        let mut skipped = 0usize;

        for block in &blocks {
            if !block.has_vector {
                skipped += 1;
                continue;
            }
            match self.chain.read_vector(block.block_num).await? {
                Some(vector) => {
                    let vector = self.fit_dims(vector, block.block_num)?;
                    self.upsert_block(block, vector).await?;
                    upserted += 1;
                }
                None => skipped += 1,
            }
        }

        let checkpoint = blocks
            .iter()
            .filter(|block| block.has_vector)
            .map(|block| block.block_num)
            .max()
            .unwrap_or(0);"}

{"content":"use anyhow::Result;
pub use cozo::{DataValue, Num};
use cozo::{DbInstance, NamedRows, ScriptMutability};
use serde_json::Value;
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::Arc;
use tracing::{info, warn};

type Params = BTreeMap<String, DataValue>;

/// Strongly-typed error for CozoDB graph operations.
///
/// Keeps `anyhow` out of the public API surface while preserving
/// ergonomic `?` propagation inside the crate.
#[derive(Debug, thiserror::Error)]
pub enum CozoError {
    #[error("CozoDB error: {0}")]
    Database(String),

    #[error("serialization error: {0}")]
    Serialization(#[from] serde_json::Error),

    #[error("{0}")]
    Other(String),
}

impl From<anyhow::Error> for CozoError {
    fn from(e: anyhow::Error) -> Self {
        Self::Other(e.to_string())
    }
}

/// Run a CozoDB script, converting the non-std Error to anyhow.
fn cozo_run(db: &DbInstance, script: &str, params: Params) -> Result<NamedRows> {
    db.run_script(script, params, ScriptMutability::Mutable)
        .map_err(|e| anyhow::anyhow!("{e}"))
}

/// Verdict returned by the compliance graph evaluation.
#[derive(Debug, Clone)]
pub struct PolicyVerdict {
    pub allow: bool,
    pub reason: String,
}

/// Full WireGuard gateway session record (mirrors op-gateway's `WireGuardSession`),
/// persisted so a gateway restart doesn't drop live sessions. `flags_json` is the
/// caller's flags map, pre-serialized to a JSON string.
#[derive(Debug, Clone)]
pub struct WgSessionRecord {
    pub session_id: String,
    pub peer_pubkey: String,
    pub psk: String,
    pub created_at: u64,
    pub expires_at: u64,
    pub is_active: bool,
    pub last_used: u64,
    pub client_ip: Option<String>,
    pub client_version: Option<String>,
    pub auth_method: String,
    pub key_rotation_count: u32,
    pub flags_json: String,
}

/// One container identity sled row (mirrors op-plugins' `ContainerIdentitySled`).
/// `btrfs_device_json` is the sled's btrfs device record pre-serialized to JSON;
/// `peer_ip`, `blob_ref`, and `btrfs_device_json` use `""` for absent.
#[derive(Debug, Clone)]
pub struct IdentitySledRecord {
    pub session_id: String,
    pub wireguard_pubkey: String,
    pub interface: String,
    pub peer_ip: String,
    pub mutation_index: i64,
    pub hashed_footprint: String,
    pub trace_id: String,
    pub schema_version: i64,
    pub vector_id: String,
    pub blob_ref: String,
    pub btrfs_device_json: String,
    pub instance_json: String,
    pub session_started_at: i64,
    pub last_seen_at: i64,
    pub active: bool,
    /// 0 = permanent (no expiry); otherwise unix seconds this identity
    /// stops being valid (temporary/consumer identities like Lovable).
    pub expires_at: i64,
}

/// One row of a session's append-only "snowball" event ledger.
#[derive(Debug, Clone)]
pub struct SessionEventRecord {
    pub session_id: String,
    pub seq: i64,
    pub kind: String,
    pub subid: String,
    pub content: String,
    pub created_at: i64,
}

/// One registered human principal row (mirrors op-plugins' `HumanPrincipal`).
///
/// Humans are not containers: `principal_id` is derived from the WireGuard
/// pubkey via `op_identity::session::derive_principal_id` (never
/// caller-supplied), so it can never collide with a container session id.
/// `display_alias` is display-only ("" = none) and never authoritative.
/// `revoked_at` = 0 means active; revocation is a permanent tombstone — the
/// row (and its pubkey mapping) is never deleted, so a revoked key can never
/// be re-registered.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct HumanPrincipalRecord {
    pub principal_id: String,
    pub human_pubkey: String,
    pub display_alias: String,
    pub registered_at: i64,
    pub revoked_at: i64,
}

/// Default on-disk location of the human_principal plugin's Cozo database.
pub const DEFAULT_HUMAN_PRINCIPAL_COZO_DB_PATH: &str = "/var/lib/op-dbus/human-principal-cozo";

/// Resolve the human_principal Cozo DB path: the
/// `OP_HUMAN_PRINCIPAL_COZO_DB_PATH` override when set, else the default.
pub fn human_principal_cozo_db_path() -> PathBuf {
    std::env::var("OP_HUMAN_PRINCIPAL_COZO_DB_PATH")
        .map(PathBuf::from)
        .unwrap_or_else(|_| PathBuf::from(DEFAULT_HUMAN_PRINCIPAL_COZO_DB_PATH))
}

/// CozoDB graph database shuttle.
///
/// Manages the unified Datalog relations:
///   - `compliance_rule`     — NIST/EU-AI-Act deny rules evaluated before mutations
///   - `subid_registry`      — canonical OSCAL subid taxonomy entries
///   - `graph_node`          — arbitrary identity-graph nodes
///   - `graph_edge`          — directed relationships between nodes
///   - `audit_event`         — append-only compliance audit log
///   - `users`               — wg_pubkey-keyed user identities (no PII)
///   - `sessions`            — session_id → wg_pubkey, with expiry
///   - `memory_namespaces`   — named MCP memory contexts
///   - `memory_entries`      — key/value entries within a namespace
#[derive(Clone)]
pub struct CozoGraphShuttle {
    pub(crate) db: Arc<DbInstance>,
}

impl CozoGraphShuttle {
    pub fn new_in_memory() -> std::result::Result<Self, CozoError> {
        let db = DbInstance::new("mem", "", Default::default()).map_err(|e| {
            CozoError::Other(format!("failed to create CozoDB in-memory instance: {e}"))
        })?;
        let s = Self { db: Arc::new(db) };
        s.seed_schema().map_err(CozoError::from)?;
        Ok(s)
    }

    pub fn new_persistent(path: PathBuf) -> std::result::Result<Self, CozoError> {
        let ps = path.to_string_lossy().to_string();
        // RocksDB is the durable storage engine beneath CozoDB.
        let db = DbInstance::new("rocksdb", &ps, Default::default())
            .map_err(|e| CozoError::Other(format!("failed to open CozoDB at {ps}: {e}")))?;
        let s = Self { db: Arc::new(db) };
        s.seed_schema().map_err(CozoError::from)?;
        Ok(s)
    }

    pub fn from_env() -> std::result::Result<Self, CozoError> {
        if let Ok(p) = std::env::var("COGNITIVE_MCP_COZO_DB_PATH") {
            Self::new_persistent(PathBuf::from(p))
        } else {
            Self::new_in_memory()
        }
    }

    fn seed_schema(&self) -> Result<()> {
        let relations = [
            // plugin × op → action(Deny/Allow) + reason + control_ref
            r#":create compliance_rule {
                plugin: String, op: String, action: String
                =>
                reason: String default "",
                control_ref: String default "",
                created_at: String default ""
            }"#,
            // canonical OSCAL subid entries
            r#":create subid_registry {
                subid: String
                =>
                category: String default "",
                component_type: String default "",
                subject: String default "",
                verb: String default "",
                facet: String default "",
                version: Int default 1,
                control_source: String default "",
                control_refs: String default "",
                statement_refs: String default "",
                registered_at: String default ""
            }"#,
            // identity-graph nodes
            r#":create graph_node {
                id: String
                =>
                label: String default "",
                props: String default "{}"
            }"#,
            // directed relationships
            r#":create graph_edge {
                src: String, rel: String, dst: String
                =>
                props: String default "{}"
            }"#,
            // append-only audit log
            r#":create audit_event {
                event_id: String
                =>
                subid: String default "",
                plugin_id: String default "",
                operation: String default "",
                actor: String default "",
                verdict: String default "allow",
                reason: String default "",
                control_ref: String default "",
                timestamp: String default ""
            }"#,
            // wg_pubkey-keyed user identities; no email or PII persisted
            r#":create users {
                wg_pubkey: String
                =>
                created_at: String default ""
            }"#,
            // full privacy router user accounts (PII stored per explicit directive)
            r#":create privacy_users {
                id: String
                =>
                email: String default "",
                email_verified: String default "false",
                wg_public_key: String default "",
                wg_private_key_encrypted: String default "",
                assigned_ip: String default "",
                privacy_quota_bytes: Int default 1073741824,
                privacy_quota_used_bytes: Int default 0,
                privacy_container_name: String default "",
                privacy_route_id: String default "",
                privacy_network_connected: String default "false",
                privacy_network_connected_at: String default "",
                google_id: String default "",
                google_email: String default "",
                api_credentials_json: String default "null",
                created_at: String default ""
            }"#,
            // session_id → wg_pubkey with optional expiry (RFC3339)
            r#":create sessions {
                session_id: String
                =>
                wg_pubkey: String default "",
                created_at: String default "",
                expires_at: String default ""
            }"#,
            // consumer account proof — wg_pubkey keyed, no email/PII
            r#":create account_sessions {
                wg_pubkey: String
                =>
                session_id: String default "",
                session_proof: String default "",
                created_at: String default ""
            }"#,
            // GhostBridge consumer operational state — session_id keyed, no email/PII
            r#":create consumer_accounts {
                session_id: String
                =>
                wg_public_key: String default "",
                wg_private_key_encrypted: String default "",
                assigned_ip: String default "",
                email_verified: String default "true",
                privacy_quota_bytes: Int default 1073741824,
                privacy_quota_used_bytes: Int default 0,
                privacy_container_name: String default "",
                privacy_route_id: String default "",
                privacy_network_connected: String default "false",
                privacy_network_connected_at: String default "",
                api_credentials_json: String default "null",
                created_at: String default ""
            }"#,
            // full WireGuard gateway session record (op-gateway::WireGuardSession),
            // persisted so restarts don't drop live sessions
            r#":create wg_sessions {
                session_id: String
                =>
                peer_pubkey: String default "",
                psk: String default "",
                created_at: Int default 0,
                expires_at: Int default 0,
                is_active: Bool default true,
                last_used: Int default 0,
                client_ip: String default "",
                client_version: String default "",
                auth_method: String default "",
                key_rotation_count: Int default 0,
                flags_json: String default "{}"
            }"#,
            // peer_pubkey → session_id, mirrors op-gateway's in-memory peer_sessions map
            r#":create wg_peer_sessions {
                peer_pubkey: String
                =>
                session_id: String default ""
            }"#,
            // named MCP memory contexts (replaces SQLite memory_namespaces)
            r#":create memory_namespaces {
                name: String
                =>
                id: String default "",
                kind: String default "custom",
                description: String default "",
                linked_task_id: String default "",
                linked_cron: String default "",
                metadata: String default "{}",
                created_at: String default "",
                updated_at: String default ""
            }"#,
            // key/value entries within a namespace (replaces SQLite memory_entries)
            r#":create memory_entries {
                namespace: String, key: String
                =>
                id: String default "",
                value: String default "null",
                tags: String default "[]",
                created_at: String default "",
                updated_at: String default "",
                expires_at: String default "",
                access_count: Int default 0,
                last_accessed: String default ""
            }"#,
            // persistent agent identity / personality (Soul Memory)
            r#":create soul_memories {
                agent_id: String
                =>
                identity: String default "",
                personality: String default "",
                traits: String default "{}",
                version: Int default 1,
                created_at: String default "",
                updated_at: String default ""
            }"#,
            // 1:1 binding from agent → owning memory namespace
            r#":create agent_namespace_bindings {
                agent_id: String
                =>
                namespace: String default "",
                created_at: String default "",
                updated_at: String default ""
            }"#,
            // one row per container identity sled (the container IS the sled IS
            // the identity; host = container zero). btrfs_device_json is the
            // sled's Cozo-registered btrfs persistence device, pre-serialized
            // ("" = none); peer_ip/blob_ref use "" for absent.
            r#":create identity_sleds {
                session_id: String
                =>
                wireguard_pubkey: String,
                interface: String default "",
                peer_ip: String default "",
                mutation_index: Int default 0,
                hashed_footprint: String default "",
                trace_id: String default "",
                schema_version: Int default 0,
                vector_id: String default "",
                blob_ref: String default "",
                btrfs_device_json: String default "",
                instance_json: String default "",
                session_started_at: Int default 0,
                last_seen_at: Int default 0,
                active: Bool default false,
                expires_at: Int default 0
            }"#,
            // append-only per-session "snowball" event ledger archive
            // (the immutable event chain is the proof; this is the queryable copy)
            r#":create session_events {
                session_id: String,
                seq: Int
                =>
                kind: String,
                subid: String default "",
                content: String default "",
                created_at: Int default 0
            }"#,
            // one row per registered human principal (humans ≠ containers;
            // principal_id is derived, never caller-supplied). revoked_at = 0
            // means active; revocation is a permanent tombstone — the row is
            // never deleted, so a revoked key can never be re-registered.
            r#":create human_principals {
                principal_id: String
                =>
                human_pubkey: String,
                display_alias: String default "",
                registered_at: Int default 0,
                revoked_at: Int default 0
            }"#,
            // human_pubkey → principal_id lookup; the pubkey is unique across
            // ALL principals, active or revoked (tombstones keep their mapping)
            r#":create human_principal_pubkeys {
                human_pubkey: String
                =>
                principal_id: String default ""
            }"#,
        ];

        for script in &relations {
            if let Err(e) = cozo_run(&self.db, script, BTreeMap::new()) {
                let msg = e.to_string();
                if !msg.contains("already exists")
                    && !msg.contains("AlreadyExists")
                    && !msg.contains("conflicts with an existing")
                {
                    eprintln!("COZO_SCHEMA_ERR: {}", msg);
                    warn!(error = %msg, "CozoDB schema init warning");
                }
            }
        }

        info!("CozoDB schema ready");
        Ok(())
    }

    // ── Raw query ──────────────────────────────────────────────────────────────

    pub fn run_query(
        &self,
        query: &str,
        params: Option<Value>,
    ) -> std::result::Result<Value, CozoError> {
        let p = params.map(json_obj_to_params).unwrap_or_default();
        let rows = cozo_run(&self.db, query, p)
            .map_err(|e| CozoError::Other(format!("CozoDB query failed: {e}")))?;
        Ok(named_rows_to_json(rows))
    }

    // ── Compliance ─────────────────────────────────────────────────────────────

    /// Evaluate (plugin_id, operation) against all Deny rules in the compliance graph.
    pub fn evaluate_mutation(&self, plugin_id: &str, operation: &str) -> PolicyVerdict {
        let query = r#"
            deny_rule[reason] :=
                *compliance_rule[plugin, op, action, reason, _, _],
                action = 'Deny',
                (plugin = $plugin || plugin = '*'),
                (op = $op || op = '*')
            ?[reason] := deny_rule[reason]"}

{"content":"//! RAG ingestion pipeline for repomix content.
//!
//! Pipeline: zip → repomix parse → enrich → chunk → Voyage embed → Qdrant upsert
//!
//! Each Qdrant point payload carries rich metadata for hover display:
//!   repo, file_path, language, symbols, doc_comments, imports, tags,
//!   is_test, line_start, line_end, chunk_index, total_chunks, content_hash

use crate::voyage::VoyageClient;
use anyhow::{Context, Result};
use qdrant_client::{
    qdrant::{
        vectors_config::Config as VectorsConfigEnum, Condition, CreateCollectionBuilder, Distance,
        Filter, PointStruct, ScoredPoint, SearchPointsBuilder, UpsertPointsBuilder,
        VectorParamsBuilder, VectorsConfig,
    },
    Payload, Qdrant, QdrantError,
};
use regex::Regex;
use serde::Serialize;
use sha2::{Digest, Sha256};
use std::{
    collections::HashMap,
    io::{BufRead, BufReader},
    path::Path,
    sync::OnceLock,
    time::Duration,
};
use tracing::{info, warn};

// ─── constants ───────────────────────────────────────────────────────────────

pub const DEFAULT_COLLECTION: &str = "repomix_rag";
/// The fused voyage-4 retrieval set — one shared embedding space, so `_large`
/// and `_lite` collections compare directly. Best available tier per language:
/// go/python/rust were re-vectorized to voyage-4-large (see ../logs
/// vectorize_lsp_4large_*), the rest remain voyage-4-lite. Rust replaced its old
/// voyage-code-3 solo collection here.
pub const DEFAULT_VOYAGE4_COLLECTIONS: &[&str] = &[
    "repos_lsp_c_cpp_voyage_4_lite",
    "repos_lsp_go_voyage_4_large",
    "repos_lsp_java_voyage_4_lite",
    "repos_lsp_python_voyage_4_large",
    "repos_lsp_rust_voyage_4_large",
    "repos_lsp_typescript_voyage_4_lite",
    "repos_specs_docs_voyage_4_lite",
];
const VECTOR_DIM: u64 = 1024; // voyage-4 default
const CHUNK_LINES: usize = 80; // ~2 kB of code per chunk
const OVERLAP_LINES: usize = 12;
const VOYAGE_BATCH: usize = 32; // points per upsert batch
const VOYAGE_RATE_DELAY_MS: u64 = 120; // ms between Voyage calls

// ─── extracted file metadata ──────────────────────────────────────────────────

#[derive(Debug, Clone, Default)]
pub struct FileMeta {
    pub language: &'static str,
    pub file_type: FileType,
    pub symbols: Vec<String>, // top-level pub items
    pub doc_comments: Vec<String>,
    pub imports: Vec<String>, // use / import / require
    pub tags: Vec<String>,    // semantic auto-tags
    pub is_test: bool,
}

#[derive(Debug, Clone, Default, PartialEq)]
pub enum FileType {
    #[default]
    Source,
    Test,
    Config,
    Docs,
    Build,
    Other,
}

impl FileType {
    fn as_str(&self) -> &'static str {
        match self {
            Self::Source => "source",
            Self::Test => "test",
            Self::Config => "config",
            Self::Docs => "docs",
            Self::Build => "build",
            Self::Other => "other",
        }
    }
}

// ─── chunk ────────────────────────────────────────────────────────────────────

#[derive(Debug)]
pub struct Chunk {
    pub repo: String,
    pub file_path: String,
    pub meta: FileMeta,
    pub content: String,    // raw chunk lines
    pub embed_text: String, // metadata header + content (what gets embedded)
    pub content_hash: String,
    pub chunk_index: usize,
    pub total_chunks: usize,
    pub line_start: usize,
    pub line_end: usize,
}

// ─── ingestion stats ──────────────────────────────────────────────────────────

#[derive(Debug, Default)]
pub struct IngestStats {
    pub files_parsed: usize,
    pub chunks_created: usize,
    pub chunks_upserted: usize,
    pub chunks_skipped: usize,
    pub errors: usize,
}

